// Server response
// { amount: number, date: string }

// Version A: lenient parsing, strict output
function handleRequestA(req: Request) {
  const amt = parseFloat(req.body.amount);
  const date = parseDate(req.body.date); // accepts many formats
  return { amount: amt, date: date.toISOString() };
}

// Version B: lenient parsing, echo raw
function handleRequestB(req: Request) {
  const amt = parseFloat(req.body.amount);
  const date = req.body.date; // preserved as-sent string
  return { amount: amt, date };
}
